import java.util.*;

class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
            // Step 1: Count frequency of each distinct number
                    Map<Integer, Integer> freqMap = new HashMap<>();
                            for (int num : nums) {
                                        freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
                                                }

                                                        // Extract frequencies into an array
                                                                int[] counts = new int[freqMap.size()];
                                                                        int idx = 0;
                                                                                for (int val : freqMap.values()) {
                                                                                            counts[idx++] = val;
                                                                                                    }

                                                                                                            // Step 2: Sort quantity in descending order
                                                                                                                    // Satisfying the largest customer requests first fails fastest and prunes branches early
                                                                                                                            Arrays.sort(quantity);
                                                                                                                                    reverse(quantity);

                                                                                                                                            return backtrack(counts, quantity, 0);
                                                                                                                                                }

                                                                                                                                                    private boolean backtrack(int[] counts, int[] quantity, int customerIdx) {
                                                                                                                                                            // Base case: all customers are satisfied
                                                                                                                                                                    if (customerIdx == quantity.length) {
                                                                                                                                                                                return true;
                                                                                                                                                                                        }

                                                                                                                                                                                                int req = quantity[customerIdx];

                                                                                                                                                                                                        for (int i = 0; i < counts.length; i++) {
                                                                                                                                                                                                                    // Prune duplicate states: if an identical frequency already failed for this requirement, skip it
                                                                                                                                                                                                                                if (i > 0 && counts[i] == counts[i - 1]) {
                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                        if (counts[i] >= req) {
                                                                                                                                                                                                                                                                                        counts[i] -= req;
                                                                                                                                                                                                                                                                                                        if (backtrack(counts, quantity, customerIdx + 1)) {
                                                                                                                                                                                                                                                                                                                            return true;
                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                            counts[i] += req; // backtrack
                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                        return false;
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                private void reverse(int[] arr) {
                                                                                                                                                                                                                                                                                                                                                                                                        int left = 0, right = arr.length - 1;
                                                                                                                                                                                                                                                                                                                                                                                                                while (left < right) {
                                                                                                                                                                                                                                                                                                                                                                                                                            int temp = arr[left];
                                                                                                                                                                                                                                                                                                                                                                                                                                        arr[left] = arr[right];
                                                                                                                                                                                                                                                                                                                                                                                                                                                    arr[right] = temp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                left++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            right--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }